// SPDX-License-Identifier: Apache-2.0
//! `war dispatch` — build the inputs to a Stage Dispatch from a Warrant's own
//! records and emit the packet (SAS §47, §33, §52).
//!
//! # What the context manifest is built from
//!
//! The Warrant's atoms, and nothing else. Each atom becomes a [`ContextItem`]
//! pinned by the sha256 of its bytes, held by `git` at the current commit.
//! The five required atoms are included; optional atoms are recorded as
//! omitted WITH a reason (§33.7). Nothing outside the Warrant is reached for —
//! §33.6 forbids silently dropping a required item, and the cheapest way to
//! honour that is to start from a set whose required members are all known.
//!
//! # What is minted here and not in the compiler
//!
//! The `dispatch_id` and the attempt's id are UUIDv7s minted here, so that
//! [`openwarrant_compiler::compile_dispatch`] stays a pure function. Two calls
//! to this command produce two different packets, correctly: they are two
//! attempts. Two calls to the compiler with the same ids produce one.

use std::fs;
use std::process::Command;

use camino::Utf8Path;
use openwarrant_compiler::dispatch::TokenInputs;
use openwarrant_compiler::{DispatchError, DispatchInputs, compile_dispatch, dispatch_json, lower};
use openwarrant_core::context::{ConflictCheck, ContextManifest};
use openwarrant_core::execution::{
    Attempt, AttemptKind, CapabilityAuthorization, ResourceEnvelope,
};
use openwarrant_core::milestones;

use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{RepoError, Repository};

/// Build and emit one dispatch.
/// What the caller asks of a compilation, beyond which stage of which Warrant.
///
/// A struct rather than five more parameters: the two paths are both
/// `Option<&Utf8Path>` and the two flags are both plain, so a positional list
/// of them is a list of things a caller can silently transpose.
#[derive(Debug, Clone, Copy)]
pub struct Options<'a> {
    /// §52: initial, replay, repair, restart.
    pub attempt_kind: AttemptKind,
    /// Required for a repair (§52.3).
    pub prior_failure_evidence: &'a [String],
    /// Write the packet here instead of stdout.
    pub emit_to: Option<&'a Utf8Path>,
    /// Write the §33 context manifest beside it.
    pub emit_context_to: Option<&'a Utf8Path>,
    /// Compile for a contract no human has signed, recording
    /// `prototype://unauthorized` as the authority it acted under. The operator
    /// types this; §27.2 leaves an agent no way to decide it.
    pub prototype: bool,
}

pub fn run(
    repo: &Repository,
    alias: &str,
    stage_id: &str,
    opts: Options<'_>,
) -> Result<Report, RepoError> {
    let Options {
        attempt_kind,
        prior_failure_evidence,
        emit_to,
        emit_context_to,
        prototype,
    } = opts;
    let dir = repo.warrant_dir(alias)?;
    let one = repo.load_warrant(&dir)?;
    let mut report = Report::default();

    // A Dispatch is the instruction an actor works from, and §47 calls it a
    // projection of an AUTHORIZED contract. Nothing here checked that: a packet
    // for a Warrant nobody had signed compiled exactly like one for a Warrant
    // the owner had, and an agent reading it could not tell the difference.
    // Prototyping before authorization is legitimate — it is how most work
    // starts — so it is admitted explicitly, named in the packet, and never the
    // default.
    let authority_ref = match repo.load_authorization(&dir) {
        Ok(Some(record)) => {
            let verdict = record.revision.authorization.as_ref().map(|auth| {
                crate::authority_check::verify(
                    repo,
                    crate::authority_check::Act::Authorize,
                    alias,
                    &auth.authorizer,
                    Some(&record.revision.contract_digest),
                )
            });
            match verdict {
                Some(v) if v.is_signed() => {
                    format!("authorization://{}", record.revision.contract_digest)
                }
                other => {
                    if !prototype {
                        report.push(Diagnostic::error(
                            "dispatch.unauthorized",
                            repo.relative(&dir.join("authorization.toml")),
                            format!(
                                "{alias}: {} — a Dispatch projects an AUTHORIZED contract (§47). Sign it (`war sign {alias} --ssh-sign`), or pass --prototype for a packet that says it acted under none",
                                other.map_or_else(
                                    || "the record carries no authorization".to_owned(),
                                    |v| v.why()
                                )
                            ),
                        ));
                        return Ok(report);
                    }
                    "prototype://unauthorized".to_owned()
                }
            }
        }
        _ => {
            if !prototype {
                report.push(Diagnostic::error(
                    "dispatch.unauthorized",
                    repo.relative(&dir),
                    format!(
                        "{alias} has no authorization record, so there is no authorized contract to project (§47). Sign it (`war sign {alias} --ssh-sign`), or pass --prototype for a packet that says it acted under none"
                    ),
                ));
                return Ok(report);
            }
            "prototype://unauthorized".to_owned()
        }
    };
    if authority_ref.starts_with("prototype://") {
        report.push(Diagnostic::warn(
            "dispatch.prototype",
            repo.relative(&dir),
            format!(
                "{alias}: compiled for an UNAUTHORIZED contract at the operator's request. The packet records `prototype://unauthorized`; no work done from it is authorized work"
            ),
        ));
    }

    let (Some(basis), Some(validated)) = (&one.basis, &one.validated) else {
        return Err(RepoError::Message(format!("{alias} could not be compiled")));
    };
    let ir = lower(basis, validated).map_err(|e| RepoError::Message(format!("{alias}: {e}")))?;

    // The stage and the milestone that cites it, from the validated graph.
    let mut graph: Option<milestones::MilestoneGraph> = None;
    for atom in basis.atoms.iter().filter(|a| a.role == "milestones") {
        let text = std::str::from_utf8(&atom.bytes).map_err(|e| {
            RepoError::Message(format!("{alias}: milestones atom is not UTF-8: {e}"))
        })?;
        graph =
            Some(milestones::parse(text).map_err(|e| RepoError::Message(format!("{alias}: {e}")))?);
    }
    let Some(graph) = graph else {
        return Err(RepoError::Message(format!(
            "{alias}: declares no milestones atom"
        )));
    };
    let Some(stage) = graph.stages.iter().find(|s| s.id == stage_id) else {
        return Err(RepoError::Message(format!(
            "{alias}: no stage {stage_id:?}. Declared: {}",
            graph
                .stages
                .iter()
                .map(|s| s.id.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        )));
    };
    let Some(milestone) = graph
        .milestones
        .iter()
        .find(|m| m.stage_refs.iter().any(|s| s == stage_id))
    else {
        return Err(RepoError::Message(format!(
            "{alias}: stage {stage_id:?} is cited by no milestone, so there is no milestone_id \
             to bind it to (§47.1)"
        )));
    };

    // §33 — the context manifest. Slice C1: stage-relevant selection —
    // required atoms, plus whatever the stage declares (atoms, sections,
    // artifacts, external refs); everything else omitted with a true reason.
    let commit = git_head(&repo.root);
    let selection = match crate::context_select::select(repo, &dir, basis, stage, commit.as_deref())
    {
        Ok(s) => s,
        Err(refusals) => {
            for r in refusals {
                report.push(Diagnostic::error(
                    r.rule,
                    repo.relative(&dir.join("atoms/45-milestones.yaml")),
                    r.message,
                ));
            }
            return Ok(report);
        }
    };
    // §33.7 (slice C2), RQ-046: the selector's per-item bytes and the stage's
    // budget, or the repository's default. The estimate and the refusal are the
    // compiler's (§47.2); this command keeps no comparison of its own, so no
    // caller can reach an actor with a packet the rule never judged.
    let budget_tokens = stage
        .budget_tokens
        .unwrap_or_else(|| repo.config.context.budget());
    let (included, omitted, item_bytes) = (selection.included, selection.omitted, selection.bytes);
    let mut context = ContextManifest {
        workspace_basis_ref: format!("basis://{}", basis.manifest_source),
        workspace_basis_digest: ir.integrity.workspace_basis_digest.clone(),
        included,
        omitted,
        unresolved: vec![],
        conflicts: vec![],
        conflict_check: ConflictCheck::default(),
        effective_classification: "internal".to_owned(),
        policy_digest: String::new(),
        compiler_digest: format!("openwarrant-cli/{}", env!("CARGO_PKG_VERSION")),
    };
    // §33.4, OW-WAR-0133 OBL-004: `conflicts: []` alone would claim a list
    // nobody checked. The record says which kind was checked (one source at
    // two versions), which was not (semantic disagreement), and what the
    // check found; a finding is then refused by the compiler, by name.
    context.conflict_check = ConflictCheck::of(&context);
    if commit.is_none() {
        report.push(Diagnostic::warn(
            "dispatch.floating-holder",
            repo.relative(&dir.join("manifest.toml")),
            format!(
                "{alias}: could not read the git HEAD, so every context item's holder has no \
                 commit_sha and is floating (§33.5). A draft may float; an authorized \
                 dispatch may not."
            ),
        ));
    }

    // §52 — the attempt. Ids are minted here; the compiler stays pure.
    let attempt = Attempt {
        id: openwarrant_core::WarUuid::mint().to_string(),
        kind: attempt_kind,
        parent_attempt_ref: if attempt_kind.requires_parent() {
            "attempt://unspecified".to_owned()
        } else {
            String::new()
        },
        basis_change: if attempt_kind == AttemptKind::Replay {
            "none".to_owned()
        } else {
            String::new()
        },
        prior_failure_evidence_refs: prior_failure_evidence.to_vec(),
        prior_work_product_ref: String::new(),
        authorized_by: authority_ref,
    };

    let compiled = compile_dispatch(DispatchInputs {
        ir: &ir,
        basis,
        milestone,
        stage,
        attempt: &attempt,
        context: &context,
        resources: ResourceEnvelope {
            network_policy: "none".to_owned(),
            ..ResourceEnvelope::default()
        },
        capability: CapabilityAuthorization {
            // Not modelled in this repository. Said so, rather than a digest
            // of nothing.
            policy_ref: "policy://none-declared".to_owned(),
            digest: String::new(),
        },
        tokens: Some(TokenInputs {
            item_bytes: &item_bytes,
            budget_tokens,
        }),
        dispatch_id: openwarrant_core::WarUuid::mint().to_string(),
    });
    let dispatch = match compiled {
        Ok(d) => d,
        // Over budget is a refusal, not a failure of the tool: it names what
        // to cut, so the fix is a cut the author makes (§33.6), not a bigger
        // number. Nothing was written and nothing journalled.
        Err(e @ DispatchError::OverBudget { .. }) => {
            report.push(Diagnostic::error(
                "dispatch.over-budget",
                repo.relative(&dir.join("atoms/45-milestones.yaml")),
                format!(
                    "{alias}/{stage_id}: {e}. Narrow the stage's context_sections, or raise \
                     budget_tokens on the stage with a reason"
                ),
            ));
            return Ok(report);
        }
        // One source at two versions: a refusal naming both, like the budget
        // (§33.4). Nothing written, nothing journalled.
        Err(e @ DispatchError::SourceConflict { .. }) => {
            report.push(Diagnostic::error(
                "dispatch.source-conflict",
                repo.relative(&dir.join("atoms/45-milestones.yaml")),
                format!(
                    "{alias}/{stage_id}: {e}. Include the source once, at the revision the \
                     stage binds to"
                ),
            ));
            return Ok(report);
        }
        Err(e) => return Err(RepoError::Message(format!("{alias}/{stage_id}: {e}"))),
    };
    let Some(tokens) = dispatch.tokens.clone() else {
        return Err(RepoError::Message(format!(
            "{alias}/{stage_id}: the compiler emitted a Dispatch with no token account"
        )));
    };

    if let Some(path) = emit_context_to {
        let text = serde_json::to_string_pretty(&context)
            .map_err(|e| RepoError::Message(e.to_string()))?;
        fs::write(path, format!("{text}\n")).map_err(|source| RepoError::Io {
            context: format!("could not write {path}"),
            source,
        })?;
        report.push(Diagnostic::pass(
            "dispatch.context-emitted",
            format!(
                "{alias}/{stage_id}: context manifest written to {path} ({} included, {} omitted)",
                context.included.len(),
                context.omitted.len()
            ),
        ));
    }
    // The compile is an event of the Warrant's history (§24): what was
    // dispatched, at what size, under what budget.
    crate::journal_cmd::record(
        &dir,
        &ir.identity.uuid.to_string(),
        "dispatch.compiled",
        &format!("agent://{}", repo.performer()),
        &serde_json::json!({
            "stage": stage_id,
            "dispatch_id": dispatch.dispatch_id,
            "dispatch_digest": dispatch.dispatch_digest,
            "estimated_tokens": tokens.estimated_tokens,
            "budget_tokens": tokens.budget_tokens,
            "method": tokens.method,
        })
        .to_string(),
    )?;
    report.push(Diagnostic::pass(
        "dispatch.tokens",
        format!(
            "{alias}/{stage_id}: ~{} tokens of context against a budget of {} ({})",
            tokens.estimated_tokens, tokens.budget_tokens, tokens.method
        ),
    ));
    let json = dispatch_json(&dispatch).map_err(|e| RepoError::Message(e.to_string()))?;
    match emit_to {
        Some(path) => {
            fs::write(path, format!("{json}\n")).map_err(|source| RepoError::Io {
                context: format!("could not write {path}"),
                source,
            })?;
            report.push(Diagnostic::pass(
                "dispatch.emitted",
                format!(
                    "{alias}/{stage_id}: dispatch {} written to {path} (digest {})",
                    dispatch.dispatch_id, dispatch.dispatch_digest
                ),
            ));
        }
        None => {
            println!("{json}");
            report.push(Diagnostic::pass(
                "dispatch.compiled",
                format!(
                    "{alias}/{stage_id}: dispatch {} (digest {})",
                    dispatch.dispatch_id, dispatch.dispatch_digest
                ),
            ));
        }
    }
    report.push(Diagnostic::pass(
        "dispatch.context",
        format!(
            "{alias}/{stage_id}: {} required atom(s) included, {} optional omitted with reason",
            context.included.len(),
            context.omitted.len()
        ),
    ));
    Ok(report)
}

/// The current commit, if this is a git checkout. `None` is reported, not
/// papered over with a placeholder that looks like a revision.
fn git_head(root: &Utf8Path) -> Option<String> {
    let out = Command::new("git")
        .args(["rev-parse", "HEAD"])
        .current_dir(root)
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let sha = String::from_utf8(out.stdout).ok()?.trim().to_owned();
    (sha.len() == 40 && sha.bytes().all(|b| b.is_ascii_hexdigit())).then_some(sha)
}

